// ── L2→L3: Update global devices cache ──────────────────────
const d       = msg.device;
const devices = global.get('devices') || {};

const prev    = devices[d.id];

// Merge state thay vi overwrite — MQTT gui tung attribute rieng le
if (prev) {
    d.state = { ...prev.state, ...d.state };
    d.raw   = { ...prev.raw,   ...d.raw };
}

const changed = !prev
    || JSON.stringify(prev.state) !== JSON.stringify(d.state);

devices[d.id] = d;
global.set('devices', devices);

msg._state_changed = changed;
msg._prev_state    = prev ? prev.state : null;
return msg;

if (!msg._state_changed) return null;
const d = msg.device;
if (d.type !== 'ac_controller' && d.type !== 'mcb') return null;

const cfg = (global.get('device_configs') || {})[d.id] || {};
const ts = d.ts || new Date().toLocaleString('sv-SE', { timeZone: 'Asia/Ho_Chi_Minh' }).replace(' ', 'T');
const state = d.state || {};

// Build data object with only present values
const data = {};
const keys = Object.keys(state);
for (const k of keys) {
    if (state[k] !== undefined && state[k] !== null) {
        data[k] = state[k];
    }
}

const payload = {
    ts: ts,
    site: 'bluCafe',
    devices: [{
        id: d.id,
        type: d.type,
        name: cfg.friendly_name || d.id,
        location: cfg.location || '',
        data: data
    }]
};

msg.topic = 'smarteos/bluCafe';
msg.payload = JSON.stringify(payload);
return msg;

const rows = msg.payload || [];
if (rows.length === 0) return null;

const configs = global.get('device_configs') || {};

const byDevice = {};
for (const r of rows) {
    if (!byDevice[r.device_id]) byDevice[r.device_id] = [];
    byDevice[r.device_id].push(r);
}

const ts = new Date().toLocaleString('sv-SE', { timeZone: 'Asia/Ho_Chi_Minh' }).replace(' ', 'T');
const devices = [];

for (const [deviceId, deviceRows] of Object.entries(byDevice)) {
    const cfg = configs[deviceId] || {};
    const type = cfg.type || 'unknown';

    const latest = {};
    for (const r of deviceRows) {
        if (!latest[r.attr_name] || r.ts > latest[r.attr_name].ts) {
            latest[r.attr_name] = r;
        }
    }

    const data = {};
    for (const [attr, r] of Object.entries(latest)) {
        let val = r.attr_value;
        if (val === null) val = r.attr_str;
        if (val === null) continue;
        if (val === 'true') val = true;
        if (val === 'false') val = false;
        data[attr] = val;
    }

    devices.push({
        id: deviceId,
        type: type,
        name: cfg.friendly_name || deviceId,
        location: cfg.location || '',
        data: data
    });
}

const payload = {
    ts: ts,
    site: 'bluCafe',
    devices: devices
};

msg.topic = 'smarteos/bluCafe';
msg.payload = JSON.stringify(payload);
return msg;
